#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}

/* TAQIB E-SERVICES — restrained, responsive platform layer */
:root{--sx-ink:#102a43;--sx-navy:#12314a;--sx-teal:#1769d2;--sx-accent:#f2b84b;--sx-muted:#627487;--sx-line:#e4ebf0;--sx-soft:#f4f7f9;--sx-white:#fff;--sx-radius:18px;--sx-shadow:0 14px 38px rgba(16,42,67,.08)}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body,body *{font-family:'Tajawal',Arial,sans-serif}
body{background:#fff!important;color:var(--sx-ink)!important;font-size:16px;line-height:1.75}
.bg-photo-container,.bg-photo,.bg-photo-overlay{display:none!important}
.page{background:#fff!important;min-height:100vh}
.centered-top-container{display:none!important}
.sx-wrap{width:min(1160px,calc(100% - 40px));margin-inline:auto}
.sx-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.97);border-bottom:1px solid var(--sx-line);backdrop-filter:blur(12px)}
.sx-header-inner{min-height:82px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.sx-brand{display:flex;align-items:center;gap:12px;color:var(--sx-ink);text-decoration:none;min-width:max-content}
.sx-mark{width:46px;height:46px;display:grid;place-items:center;border-radius:14px;background:var(--sx-navy);color:#fff}
.sx-mark svg{width:27px;height:27px}
.sx-brand-name{font-weight:800;font-size:19px;line-height:1.15;letter-spacing:.01em}
.sx-brand-name small{display:block;color:var(--sx-muted);font:700 10px/1.6 Arial,sans-serif;letter-spacing:.14em}
.sx-nav{display:flex;align-items:center;justify-content:center;gap:clamp(12px,2vw,28px);flex:1}
.sx-nav a{color:#385268;text-decoration:none;font-weight:600;font-size:15px;white-space:nowrap}
.sx-nav a:hover,.sx-nav a:focus{color:var(--sx-teal)}
.sx-head-actions{display:flex;align-items:center;gap:12px}
.sx-search{display:flex;align-items:center;gap:6px}
.sx-search input{width:145px;border:1px solid var(--sx-line);border-radius:999px;padding:9px 13px;outline:none;background:#fff;font-size:14px}
.sx-search input:focus{border-color:var(--sx-teal);box-shadow:0 0 0 3px rgba(8,126,131,.12)}
.sx-search button,.sx-button{border:0;border-radius:999px;background:var(--sx-teal);color:#fff;padding:11px 20px;font-weight:700;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;transition:transform .2s,background .2s}
.sx-search button{width:40px;height:40px;padding:0;font-size:16px}
.sx-button:hover,.sx-search button:hover{background:#06666b;transform:translateY(-1px);color:#fff}
.sx-button--outline{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.55)}
.sx-hero{position:relative;overflow:hidden;color:#fff;background:radial-gradient(circle at 78% 30%,rgba(47,130,235,.42),transparent 28%),linear-gradient(115deg,#0b2038 0%,#123a63 58%,#1769d2 100%);min-height:540px;display:flex;align-items:center}
.sx-hero:after{content:'';position:absolute;inset:auto 0 0;height:7px;background:var(--sx-accent)}
.sx-hero-content{position:relative;z-index:1;padding:84px 0 92px;max-width:690px}
.sx-eyebrow{display:inline-flex;align-items:center;gap:10px;color:#f4c970;font-weight:700;letter-spacing:.08em;font-size:14px}
.sx-eyebrow:before{content:'';width:30px;height:2px;background:currentColor}
.sx-hero h1{font-size:clamp(36px,5.5vw,62px);line-height:1.12;letter-spacing:-.025em;color:#fff;margin:18px 0 18px;font-weight:800}
.sx-hero p{font-size:clamp(17px,2vw,20px);color:rgba(255,255,255,.9);max-width:590px;margin:0 0 28px}
.sx-hero-actions{display:flex;flex-wrap:wrap;gap:12px}
.sx-section{padding:78px 0}
.sx-section--soft{background:var(--sx-soft)}
.sx-section-head{text-align:center;max-width:700px;margin:0 auto 38px}
.sx-kicker{color:var(--sx-teal);font-size:14px;font-weight:800;letter-spacing:.08em}
.sx-section h2{color:var(--sx-ink);font-size:clamp(28px,4vw,40px);line-height:1.2;margin:10px 0 12px;font-weight:800}
.sx-section-head p,.sx-about-copy p{color:var(--sx-muted);font-size:17px;margin:0}
.sx-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.sx-card{height:100%;background:#fff;border:1px solid var(--sx-line);border-radius:var(--sx-radius);padding:28px;box-shadow:0 6px 20px rgba(16,42,67,.035);transition:transform .2s,box-shadow .2s}
.sx-card:hover{transform:translateY(-4px);box-shadow:var(--sx-shadow)}
.sx-card-icon{width:52px;height:52px;display:grid;place-items:center;border-radius:15px;background:#e9f5f4;color:var(--sx-teal);margin-bottom:18px}
.sx-card-icon svg{width:27px;height:27px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.sx-card h3{margin:0 0 9px;font-size:21px;color:var(--sx-ink);font-weight:800}
.sx-card p{margin:0;color:var(--sx-muted);font-size:16px}
.sx-about{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
.sx-about-panel{min-height:280px;border-radius:24px;background:linear-gradient(135deg,#143650,#0b777a);color:#fff;padding:34px;display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}
.sx-about-panel:before,.sx-about-panel:after{content:'';position:absolute;border:1px solid rgba(255,255,255,.15);border-radius:50%;width:300px;height:300px;top:-145px;left:-80px}
.sx-about-panel:after{width:200px;height:200px;top:-95px;left:-30px}
.sx-about-panel strong{font-size:28px;line-height:1.25;position:relative;z-index:1}
.sx-about-copy .sx-kicker{display:block}
.sx-values{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}
.sx-values span{border:1px solid var(--sx-line);border-radius:999px;padding:7px 13px;color:#37556b;font-weight:600;font-size:14px}
.sx-news-intro{padding:58px 0 18px}
.sx-news-intro .sx-section-head{margin-bottom:14px}
.sx-contact{background:var(--sx-navy);color:#fff;padding:48px 0}
.sx-contact-inner{display:flex;align-items:center;justify-content:space-between;gap:28px}
.sx-contact h2{font-size:30px;color:#fff;margin:0 0 7px}
.sx-contact p{margin:0;color:rgba(255,255,255,.78);font-size:16px}
.sx-contact .sx-button{background:var(--sx-accent);color:#152d40}
.page_body{padding-top:0!important}
.centered{max-width:none!important}
.centered-top-placeholder{display:none!important}
.main{max-width:1160px!important;width:calc(100% - 40px)!important;margin:0 auto!important;padding:16px 0 60px!important;float:none!important}
.blog-posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.post-outer-container,.post-outer{border:1px solid var(--sx-line)!important;border-radius:18px!important;background:#fff!important;box-shadow:0 5px 20px rgba(16,42,67,.045)!important;padding:24px!important;margin:0 0 22px!important}
.post-title,.post-title a{font-weight:800!important;color:var(--sx-ink)!important;line-height:1.35!important}
.post-body{font-size:17px!important;line-height:1.9!important;color:#40566a!important}
.post-body img{max-width:100%;height:auto;border-radius:12px}
.post-footer,.post-header{color:var(--sx-muted)!important}
.blog-pager a,.blog-pager-older-link,.blog-pager-newer-link{border-radius:999px;background:var(--sx-teal);color:#fff!important;padding:9px 16px;text-decoration:none}
.sidebar-container{display:none!important}
.page_body .centered{display:block!important}
.footer{background:#f4f7f9!important;color:#65798a!important;border-top:1px solid var(--sx-line)!important;padding:22px 20px!important;text-align:center!important}
.footer a{color:var(--sx-teal)!important}
.widget.Label,.widget.BlogArchive{border:1px solid var(--sx-line);border-radius:16px;padding:18px;margin:16px auto;max-width:1160px}
@media(max-width:980px){.sx-header-inner{gap:14px}.sx-nav{gap:12px}.sx-search input{width:110px}.sx-grid{gap:14px}.sx-card{padding:22px}}
@media(max-width:760px){.sx-header{position:relative}.sx-header-inner{min-height:72px;flex-wrap:wrap;padding:10px 0}.sx-nav{order:3;width:100%;justify-content:flex-start;overflow-x:auto;padding:5px 0 3px;scrollbar-width:none}.sx-nav::-webkit-scrollbar{display:none}.sx-nav a{font-size:14px}.sx-brand-name{font-size:17px}.sx-mark{width:42px;height:42px}.sx-search input{width:min(29vw,130px)}.sx-search button{width:38px;height:38px}.sx-head-actions .sx-cta{display:none}.sx-hero{min-height:470px;background-position:57% center}.sx-hero-content{padding:70px 0 76px}.sx-section{padding:58px 0}.sx-grid{grid-template-columns:1fr}.sx-card{padding:23px}.sx-about{grid-template-columns:1fr;gap:24px}.sx-about-panel{min-height:230px}.sx-contact-inner{align-items:flex-start;flex-direction:column}.blog-posts{grid-template-columns:1fr}.main{width:calc(100% - 28px)!important}.post-outer-container,.post-outer{padding:18px!important}}
@media(max-width:420px){.sx-wrap{width:calc(100% - 28px)}.sx-brand{gap:8px}.sx-brand-name{font-size:15px}.sx-brand-name small{font-size:9px}.sx-search input{width:88px}.sx-hero h1{font-size:36px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.sx-card,.sx-button,.sx-search button{transition:none}}


/* Ta'qib e-services platform layer */
.sx-hero{isolation:isolate;padding-inline:0}
.sx-hero:before{content:'';position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.16) 1px,transparent 1px);background-size:22px 22px;opacity:.3;mask-image:linear-gradient(90deg,transparent 32%,#000 100%);z-index:-1}
.sx-hero-content{max-width:660px}
.sx-hero-visual{position:absolute;inset-inline-end:max(5vw,calc((100vw - 1160px)/2));top:50%;transform:translateY(-50%);width:min(340px,29vw);z-index:1}
.sx-visual-card{padding:28px;border:1px solid rgba(255,255,255,.22);border-radius:24px;background:rgba(255,255,255,.12);backdrop-filter:blur(14px);box-shadow:0 25px 70px rgba(0,0,0,.22);display:flex;flex-direction:column;gap:15px}
.sx-visual-kicker{color:#d9e9ff;font-weight:700;font-size:14px}.sx-visual-card strong{font-size:28px;line-height:1.3;color:#fff}.sx-visual-line{height:1px;background:rgba(255,255,255,.25);margin:2px 0}.sx-visual-row{display:flex;align-items:center;gap:10px;color:#f1f7ff;font-size:15px}.sx-visual-row i{width:24px;height:24px;border-radius:8px;background:rgba(255,255,255,.18);display:inline-block}
.sx-hero-points{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:26px;color:rgba(255,255,255,.82);font-size:14px}.sx-hero-points span:before{content:'✓';color:#ffd36c;margin-inline-end:7px;font-weight:800}
.sx-card-icon{font-size:15px;font-weight:800;letter-spacing:.06em}.sx-card-link{display:inline-flex;align-items:center;gap:8px;margin-top:19px;color:var(--sx-teal);text-decoration:none;font-weight:800}.sx-card-link:hover{text-decoration:underline}
.sx-tracking{display:grid;grid-template-columns:.9fr 1.1fr;gap:48px;align-items:center}.sx-tracking-copy h2{font-size:clamp(28px,4vw,40px);line-height:1.2;margin:10px 0 14px;color:var(--sx-ink)}.sx-tracking-copy p{color:var(--sx-muted);font-size:17px;margin:0 0 22px}.sx-track-panel{border:1px solid var(--sx-line);border-radius:22px;padding:26px;background:#fff;box-shadow:var(--sx-shadow)}.sx-track-panel-head{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--sx-line);padding-bottom:18px}.sx-track-icon{width:42px;height:42px;display:grid;place-items:center;background:#eaf3ff;color:#1769d2;border-radius:13px;font-weight:800}.sx-track-panel-head strong,.sx-track-panel-head small{display:block}.sx-track-panel-head strong{color:var(--sx-ink);font-size:17px}.sx-track-panel-head small{color:var(--sx-muted);font-size:13px}.sx-status{margin-inline-start:auto;border-radius:999px;background:#fff5df;color:#8a6215;padding:5px 10px;font-size:12px;font-weight:800;white-space:nowrap}.sx-track-placeholder{padding-top:20px}.sx-track-placeholder-label{display:block;color:#385268;font-weight:700;font-size:14px;margin-bottom:8px}.sx-track-input{border:1px solid var(--sx-line);border-radius:12px;padding:13px 15px;color:#91a0ad;background:#f8fafc;font-size:14px}.sx-track-disabled{margin-top:13px;opacity:.56;cursor:not-allowed!important}.sx-track-note{margin:12px 0 0;color:#7b8996;font-size:12px}
.sx-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.sx-step{background:#fff;border:1px solid var(--sx-line);border-radius:18px;padding:24px}.sx-step>span{width:42px;height:42px;border-radius:13px;background:#eaf3ff;color:#1769d2;display:grid;place-items:center;font-size:19px;font-weight:800}.sx-step h3{font-size:20px;margin:16px 0 6px;color:var(--sx-ink)}.sx-step p{margin:0;color:var(--sx-muted)}
.sx-faq{max-width:850px;margin:0 auto}.sx-faq details{background:#fff;border:1px solid var(--sx-line);border-radius:14px;padding:0 20px;margin:12px 0}.sx-faq summary{cursor:pointer;list-style:none;padding:18px 28px 18px 0;color:var(--sx-ink);font-weight:800;position:relative}.sx-faq summary::-webkit-details-marker{display:none}.sx-faq summary:after{content:'+';position:absolute;inset-inline-end:0;color:var(--sx-teal);font-size:20px;top:14px}.sx-faq details[open] summary:after{content:'−'}.sx-faq details p{color:var(--sx-muted);margin:0;padding:0 0 18px}
.sx-platform-footer{background:#091c30;color:#d6e2ed;padding:28px 20px;text-align:center}.sx-platform-footer-inner{width:min(1160px,100%);margin:auto;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.sx-platform-footer p{margin:0;font-size:14px}.sx-platform-footer strong{color:#fff}.sx-platform-footer .sx-footer-note{color:#9cb0c2;font-size:13px}.widget.Attribution,#Attribution1,.footer .blogger,.footer .image-attribution{display:none!important}
@media(max-width:980px){.sx-hero-visual{inset-inline-end:22px;width:29vw}.sx-hero-content{max-width:58%}.sx-tracking{gap:26px}}
@media(max-width:760px){.sx-hero{min-height:0}.sx-hero-content{max-width:100%;padding:62px 0 42px}.sx-hero-visual{position:relative;inset:auto;transform:none;width:min(calc(100% - 40px),440px);margin:0 auto 34px}.sx-hero{display:flex;flex-direction:column;align-items:stretch}.sx-hero-points{gap:6px 14px}.sx-tracking{grid-template-columns:1fr;gap:25px}.sx-steps{grid-template-columns:1fr}.sx-platform-footer-inner{justify-content:center;text-align:center}}
@media(max-width:420px){.sx-visual-card{padding:22px}.sx-visual-card strong{font-size:24px}.sx-track-panel{padding:19px}}


/* Sanam Classifieds theme overrides */
:root{--sx-ink:#172b3a;--sx-muted:#667887;--sx-line:#e4eaf0;--sx-soft:#f5f7f9;--sx-navy:#172b3a;--sx-teal:#16827d;--sx-accent:#e8b85b}
body{font-family:'Tajawal',Arial,sans-serif!important;background:#f5f7f9!important;color:#172b3a}
.sx-header-inner{min-height:76px}.sx-mark{font-size:24px;font-weight:800;background:#172b3a}
.sx-market-hero{background:linear-gradient(115deg,#132a3c,#1c4658 65%,#267b78);min-height:490px}
.sx-market-search{display:flex;gap:10px;max-width:610px;background:#fff;padding:7px;border-radius:14px;margin:22px 0 18px;box-shadow:0 14px 36px rgba(0,0,0,.12)}
.sx-market-search input{flex:1;min-width:0;border:0;outline:0;padding:12px 15px;color:#172b3a;background:transparent}
.sx-market-search .sx-button{border:0;white-space:nowrap}
.sx-category-grid .sx-card{display:block;text-decoration:none;color:inherit;transition:transform .2s,box-shadow .2s}
.sx-category-grid .sx-card:hover{transform:translateY(-4px);box-shadow:0 14px 35px rgba(20,45,65,.1)}
.sx-category-grid .sx-card-link{display:inline-block;margin-top:10px;color:#16827d;font-weight:800}
#latest-ads{padding-bottom:18px}
#main{max-width:1160px;margin:0 auto;padding:0 20px 60px}
.main-heading{font-size:25px;font-weight:800;color:#172b3a}
.blog-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.blog-posts .post-outer{margin:0!important;padding:0!important;min-width:0}
.blog-posts .post-outer-container,.blog-posts .post{height:100%;background:#fff;border:1px solid #e5ebf0;border-radius:16px;overflow:hidden;box-shadow:0 4px 16px rgba(20,45,65,.045)}
.blog-posts .post-title{font-family:'Tajawal',Arial,sans-serif!important;font-size:20px!important;font-weight:800!important;line-height:1.45}
.blog-posts .post-body,.blog-posts .post-snippet{color:#647584;line-height:1.9}
.blog-posts .snippet-thumbnail img,.blog-posts .post-body img{max-width:100%;height:auto;object-fit:cover}
.post-footer,.post-header{color:#82909b}
.post-labels a{display:inline-block;background:#edf5f4;color:#167a76!important;border-radius:20px;padding:5px 10px;margin:3px;text-decoration:none}
#comments{background:#fff;border:1px solid #e5ebf0;border-radius:16px;padding:22px;margin-top:24px}
.sx-platform-footer{background:#132a3c}
@media(max-width:900px){.sx-nav{display:none}.blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.sx-wrap{width:calc(100% - 28px)}.sx-header-inner{min-height:68px}.sx-head-actions .sx-search{display:none}.sx-head-actions .sx-cta{padding:10px 13px;font-size:13px}.sx-market-hero{min-height:0}.sx-market-search{flex-direction:column}.sx-market-search .sx-button{width:100%}.blog-posts{grid-template-columns:1fr}#main{padding-inline:14px}.sx-section{padding:52px 0}}


/* Listing actions: local-device likes + native Blogger comments */
.sx-post-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:16px 0 4px;padding-top:13px;border-top:1px solid #edf0f3}
.sx-post-action{display:inline-flex;align-items:center;gap:7px;border:1px solid #e1e8ed;border-radius:9px;background:#fff;color:#536675;padding:8px 12px;font:700 13px 'Tajawal',Arial,sans-serif;text-decoration:none;cursor:pointer;transition:.18s}
.sx-post-action:hover{border-color:#16827d;color:#16827d}
.sx-post-action[aria-pressed=true]{background:#eaf5f3;border-color:#b8ded9;color:#11736e}
.sx-post-action svg{width:16px;height:16px;flex:none}
.sx-like-count{font-variant-numeric:tabular-nums}
@media(max-width:600px){.sx-post-actions{gap:8px}.sx-post-action{padding:8px 10px}}


/* Full marketplace interface */
.sx-marketplace{padding:18px 0 60px;background:#f5f7f9}
.sx-market-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin:0 0 20px}
.sx-market-toolbar h2{margin:0;font-size:26px;color:#172b3a}
.sx-market-count{font-size:13px;color:#71808c}
.sx-market-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:22px;align-items:start}
.sx-market-sidebar,.sx-market-main{background:#fff;border:1px solid #e5ebf0;border-radius:16px}
.sx-market-sidebar{padding:18px;position:sticky;top:16px}
.sx-market-sidebar h3{font-size:16px;margin:0 0 13px}
.sx-market-filter{display:flex;flex-direction:column;gap:5px}
.sx-market-filter button{border:0;background:transparent;text-align:right;padding:10px 11px;border-radius:9px;color:#566978;font:600 14px 'Tajawal',Arial;cursor:pointer}
.sx-market-filter button:hover,.sx-market-filter button.active{background:#edf5f4;color:#117a74}
.sx-market-main{padding:18px;min-width:0}
.sx-market-main-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}
.sx-market-main-head strong{font-size:18px}
.sx-market-sort{border:1px solid #e1e8ed;border-radius:9px;padding:9px 12px;background:#fff;color:#526473;font:14px 'Tajawal',Arial}
.sx-listing-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.sx-listing-card{border:1px solid #e8edf1;border-radius:13px;overflow:hidden;min-width:0;background:#fff;transition:.18s}
.sx-listing-card:hover{transform:translateY(-3px);box-shadow:0 10px 24px #142d4110}
.sx-listing-image{height:148px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#e6efef,#d7e4e6);font-size:48px;position:relative}
.sx-listing-image img{width:100%;height:100%;object-fit:cover}
.sx-listing-tag{position:absolute;top:10px;right:10px;background:#fff;border-radius:20px;padding:4px 9px;font-size:11px;color:#167a74;font-weight:800}
.sx-listing-body{padding:13px}
.sx-listing-body h3{font-size:15px;line-height:1.5;margin:0 0 8px;color:#203545;min-height:45px}
.sx-listing-price{font-size:17px;font-weight:800;color:#167a74;margin:0 0 9px}
.sx-listing-meta{display:flex;justify-content:space-between;gap:8px;color:#82909b;font-size:11px}
.sx-listing-open{display:block;width:100%;margin-top:12px;border:1px solid #dce7e8;background:#f7fbfa;color:#167a74;border-radius:8px;padding:8px;font:700 13px 'Tajawal',Arial;cursor:pointer}
.sx-listing-empty{grid-column:1/-1;padding:45px 15px;text-align:center;color:#7c8b96}
.sx-market-submit{position:fixed;z-index:50;left:20px;bottom:20px;background:#16827d;color:white;border:0;border-radius:999px;padding:14px 21px;font:800 15px 'Tajawal',Arial;box-shadow:0 8px 25px #0d514b40;cursor:pointer}
.sx-market-modal{position:fixed;inset:0;z-index:1000;background:#10233299;display:none;align-items:center;justify-content:center;padding:16px}
.sx-market-modal.open{display:flex}
.sx-market-dialog{background:#fff;width:min(620px,100%);max-height:92vh;overflow:auto;border-radius:18px;padding:22px;box-shadow:0 20px 70px #0003}
.sx-market-dialog-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:15px}
.sx-market-dialog-head h2{font-size:21px;margin:0}
.sx-market-close{border:0;background:#f1f4f6;border-radius:50%;width:36px;height:36px;font-size:22px;cursor:pointer}
.sx-market-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.sx-market-field{display:flex;flex-direction:column;gap:6px}
.sx-market-field.full{grid-column:1/-1}
.sx-market-field label{font-size:13px;font-weight:700;color:#425565}
.sx-market-field input,.sx-market-field select,.sx-market-field textarea{width:100%;box-sizing:border-box;border:1px solid #dfe7ec;border-radius:9px;padding:11px;background:#fff;font:14px 'Tajawal',Arial;color:#243b4c}
.sx-market-field textarea{min-height:90px;resize:vertical}
.sx-market-disclaimer{grid-column:1/-1;background:#fff8e8;color:#85672a;padding:11px;border-radius:9px;font-size:12px;line-height:1.7}
.sx-market-form button{grid-column:1/-1;border:0;background:#16827d;color:#fff;border-radius:10px;padding:13px;font:800 15px 'Tajawal',Arial;cursor:pointer}
.sx-market-detail{display:flex;flex-direction:column;gap:10px}
.sx-market-detail .sx-detail-price{font-size:22px;font-weight:800;color:#16827d}
.sx-market-detail p{line-height:1.9;color:#596d7b}
.sx-market-notice{background:#edf6f4;color:#176d68;border-radius:9px;padding:11px;font-size:13px;margin-bottom:14px}
.sx-market-hero .sx-hero-actions{display:flex;gap:10px;flex-wrap:wrap}
@media(max-width:900px){.sx-market-layout{grid-template-columns:1fr}.sx-market-sidebar{position:static}.sx-market-filter{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.sx-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){.sx-listing-grid{grid-template-columns:1fr 1fr;gap:9px}.sx-listing-image{height:115px}.sx-listing-body{padding:10px}.sx-listing-body h3{font-size:13px;min-height:39px}.sx-listing-price{font-size:15px}.sx-listing-meta{font-size:10px;flex-direction:column;gap:3px}.sx-market-main{padding:11px}.sx-market-filter{grid-template-columns:repeat(2,minmax(0,1fr))}.sx-market-form{grid-template-columns:1fr}.sx-market-field.full,.sx-market-disclaimer,.sx-market-form button{grid-column:1}.sx-market-submit{left:12px;bottom:12px;padding:12px 17px}}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
(function(){
  'use strict';
  var storageKey='snam-market-likes-v1';
  function readLikes(){try{return JSON.parse(localStorage.getItem(storageKey)||'{}')}catch(e){return {}}}
  function writeLikes(data){try{localStorage.setItem(storageKey,JSON.stringify(data))}catch(e){}}
  function initMarketActions(){
    var posts=document.querySelectorAll('.blog-posts .post-outer, .blog-posts .post-outer-container, body.item-view .post-outer, body.item-view .post-outer-container');
    posts.forEach(function(wrap){
      if(wrap.classList.contains('post-outer-container') && wrap.querySelector('.post-outer')) return;
      if(wrap.querySelector('.sx-post-actions')) return;
      var titleLink=wrap.querySelector('.post-title a, h3 a, h2 a');
      var permalink=titleLink ? titleLink.href : location.href;
      var key='post:'+permalink;
      var liked=!!readLikes()[key];
      var bar=document.createElement('div');bar.className='sx-post-actions';
      var like=document.createElement('button');like.type='button';like.className='sx-post-action sx-like-button';like.setAttribute('aria-pressed',liked?'true':'false');
      like.innerHTML='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M7 10v11H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3Zm0 0 5-8c1.8 0 2.7 1.4 2.2 3.1L13 10h5.4a2.5 2.5 0 0 1 2.4 3.2l-1.8 6A2.5 2.5 0 0 1 16.6 21H7" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg><span></span>';
      like.querySelector('span').textContent=liked?'أعجبني':'إعجاب';
      like.addEventListener('click',function(){
        var current=readLikes();var next=!current[key];
        if(next){current[key]=1}else{delete current[key]}
        writeLikes(current);like.setAttribute('aria-pressed',next?'true':'false');like.querySelector('span').textContent=next?'أعجبني':'إعجاب';
      });
      var comments=document.createElement('a');comments.className='sx-post-action';comments.href=permalink+(permalink.indexOf('#')===-1?'#comments':'');
      comments.innerHTML='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l-2 2v-6a7.5 7.5 0 1 1 17-3.5Z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg><span>التعليقات</span>';
      bar.appendChild(like);bar.appendChild(comments);
      (wrap.querySelector('.post-footer, .post-bottom, .post-body')||wrap).appendChild(bar);
    });
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initMarketActions)}else{initMarketActions()}
  var observer=new MutationObserver(initMarketActions);
  observer.observe(document.documentElement,{childList:true,subtree:true});
  setTimeout(function(){observer.disconnect()},10000);
})();

(function(){
'use strict';
var demo=[
{t:'شقة غرفتين وصالة للإيجار بحي هادئ',c:'عقارات',p:'1,800 ريال / شهرياً',city:'الرياض',date:'اليوم',i:'🏠',d:'شقة نظيفة ومجددة، غرفتا نوم وصالة ومطبخ ودورة مياه، قريبة من الخدمات. بيانات تجريبية للعرض.'},
{t:'أرض سكنية 300 متر في مخطط جديد',c:'عقارات',p:'185,000 ريال',city:'الخرج',date:'اليوم',i:'🏡',d:'أرض سكنية بصك إلكتروني افتراضي لأغراض العرض فقط.'},
{t:'فيلا عائلية دورين مع حوش',c:'عقارات',p:'780,000 ريال',city:'جدة',date:'أمس',i:'🏘️',d:'فيلا واسعة بتصميم عائلي. هذا إعلان تجريبي وليس عرضاً حقيقياً.'},
{t:'تويوتا كامري 2021 حالة ممتازة',c:'سيارات',p:'69,000 ريال',city:'الرياض',date:'اليوم',i:'🚘',d:'سيارة تجريبية لعرض شكل بطاقة الإعلان، يرجى عدم اعتبار البيانات حقيقية.'},
{t:'هيونداي إلنترا 2019 اقتصادية',c:'سيارات',p:'38,500 ريال',city:'الدمام',date:'أمس',i:'🚗',d:'مواصفات وسعر افتراضيان لعرض واجهة السوق.'},
{t:'دباب توصيل بحالة جيدة',c:'سيارات',p:'4,200 ريال',city:'مكة',date:'قبل يومين',i:'🛵',d:'إعلان توضيحي تجريبي.'},
{t:'آيفون 14 برو سعة 256 جيجا',c:'أجهزة',p:'2,150 ريال',city:'الرياض',date:'اليوم',i:'📱',d:'جهاز تجريبي معروض لاختبار التصميم.'},
{t:'لابتوب للأعمال والدراسة',c:'أجهزة',p:'1,850 ريال',city:'أبها',date:'أمس',i:'💻',d:'لابتوب بمواصفات افتراضية لعرض نموذج الإعلان.'},
{t:'شاشة تلفزيون ذكية 55 بوصة',c:'أجهزة',p:'1,100 ريال',city:'الطائف',date:'قبل يومين',i:'📺',d:'تفاصيل المنتج افتراضية.'},
{t:'مطلوب محاسب للعمل بدوام كامل',c:'وظائف',p:'راتب يحدد بعد المقابلة',city:'الرياض',date:'اليوم',i:'💼',d:'فرصة وظيفية افتراضية لأغراض اختبار واجهة المنصة.'},
{t:'مصمم جرافيك للعمل عن بعد',c:'وظائف',p:'حسب الخبرة',city:'عن بعد',date:'أمس',i:'🎨',d:'إعلان وظيفة تجريبي.'},
{t:'كنب زاوية مع طاولة وسط',c:'أثاث',p:'1,300 ريال',city:'جدة',date:'اليوم',i:'🛋️',d:'أثاث منزلي افتراضي.'},
{t:'غرفة نوم كاملة بحالة ممتازة',c:'أثاث',p:'2,400 ريال',city:'المدينة',date:'أمس',i:'🛏️',d:'إعلان تجريبي لعرض تصنيف الأثاث.'},
{t:'خدمات نقل عفش داخل المدينة',c:'خدمات',p:'تبدأ من 150 ريال',city:'الرياض',date:'اليوم',i:'🚚',d:'خدمة افتراضية لشرح شكل الإعلان.'},
{t:'تصميم مواقع ومتاجر إلكترونية',c:'خدمات',p:'حسب الطلب',city:'كل المناطق',date:'أمس',i:'🖥️',d:'خدمة تجريبية لعرض قسم الخدمات.'}
];
var cats=['الكل','عقارات','سيارات','أجهزة','وظائف','أثاث','خدمات'];
var userKey='snam-market-user-listings-v1';
var active='الكل',query='';
function esc(v){return String(v||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function users(){try{return JSON.parse(localStorage.getItem(userKey)||'[]')}catch(e){return []}}
function save(a){try{localStorage.setItem(userKey,JSON.stringify(a));return true}catch(e){return false}}
function bloggerPosts(){
 var out=[],seen={};
 document.querySelectorAll('.blog-posts .post-outer, .blog-posts .post-outer-container, .blog-posts article').forEach(function(w){
  if(w.classList.contains('post-outer-container')&&w.querySelector('.post-outer'))return;
  var title=w.querySelector('.post-title a, h3.post-title a, h2.post-title a, .post-title');
  var link=title&&title.href?title.href:(w.querySelector('a[rel="bookmark"]')||{}).href;
  var name=(title?title.textContent:w.querySelector('h1,h2,h3')?.textContent||'').trim();
  if(!name||seen[name])return;seen[name]=1;
  var body=w.querySelector('.post-body,.entry-content,.post-snippet');
  var desc=body?(body.innerText||body.textContent||'').trim():'';
  var labels=Array.from(w.querySelectorAll('.post-labels a, .post-labels .label-name')).map(function(a){return a.textContent.trim()});
  var known=['عقارات','سيارات','أجهزة','وظائف','أثاث','خدمات'];
  var category=known.find(function(c){return labels.indexOf(c)>-1})||labels[0]||'أخرى';
  var image=body&&body.querySelector('img');
  var price=(desc.match(/(?:السعر|المطلوب|الإيجار)\\s*[:：-]?\\s*([^\\n،]+)/)||[])[1]||'تواصل لمعرفة السعر';
  var city=(desc.match(/(?:المدينة|الموقع|المدينة\\s*\\/\\s*الحي)\\s*[:：-]?\\s*([^\\n،]+)/)||[])[1]||'غير محدد';
  var dateNode=w.querySelector('.published,.post-timestamp time');
  out.push({t:name,c:category,p:price,city:city,date:dateNode?(dateNode.textContent||dateNode.getAttribute('datetime')||''):'من بلوجر',i:'🛍️',d:desc.slice(0,1800),image:image?image.src:'',url:link||'',source:'blogger'});
 });
 return out;
}
function all(){return bloggerPosts().concat(users().map(function(x){x.source='local';return x}),demo.map(function(x){x.source='demo';return x}))}
function render(){
 var root=document.getElementById('sx-market-listings');if(!root)return;
 var items=all().filter(function(x){return (active==='الكل'||x.c===active)&&(!query||(x.t+' '+x.c+' '+x.city+' '+x.d).toLowerCase().indexOf(query.toLowerCase())>-1)});
 var count=root.querySelector('.sx-market-count');if(count)count.textContent=items.length+' إعلان';
 var grid=root.querySelector('.sx-listing-grid');if(!grid)return;
 grid.innerHTML=items.map(function(x,n){return '<article class="sx-listing-card"><div class="sx-listing-image">'+(x.image?'<img src="'+esc(x.image)+'" alt="" loading="lazy" onerror="this.style.display=\'none\'"/>':esc(x.i||'🛍️'))+'<span class="sx-listing-tag">'+esc(x.c)+'</span></div><div class="sx-listing-body"><h3>'+esc(x.t)+'</h3><div class="sx-listing-price">'+esc(x.p||'على السوم')+'</div><div class="sx-listing-meta"><span>📍 '+esc(x.city)+'</span><span>'+esc(x.date||'الآن')+'</span></div><button class="sx-listing-open" type="button" data-detail="'+n+'">عرض التفاصيل</button></div></article>'}).join('')||'<div class="sx-listing-empty">لا توجد إعلانات مطابقة. جرّب قسماً آخر أو أضف إعلانك.</div>';
 grid.querySelectorAll('[data-detail]').forEach(function(btn){btn.addEventListener('click',function(){showDetail(items[Number(btn.getAttribute('data-detail'))])})});
}
function showDetail(x){
 var modal=document.getElementById('sx-market-detail-modal');if(!modal)return;
 modal.querySelector('.sx-market-dialog').innerHTML='<div class="sx-market-dialog-head"><h2>'+esc(x.t)+'</h2><button class="sx-market-close" type="button" data-close>×</button></div><div class="sx-market-detail"><div class="sx-listing-image">'+(x.image?'<img src="'+esc(x.image)+'" alt=""/>':esc(x.i||'🛍️'))+'</div><div class="sx-detail-price">'+esc(x.p||'على السوم')+'</div><div>📍 '+esc(x.city)+'　 ·　 '+esc(x.c)+'</div><p>'+esc(x.d)+'</p>'+(x.url?'<a class="sx-button" href="'+esc(x.url)+'" target="_blank" rel="noopener">فتح منشور بلوجر</a>':'')+(x.phone?'<a class="sx-button" href="https://wa.me/'+esc(x.phone.replace(/\D/g,''))+'" target="_blank" rel="noopener">تواصل عبر واتساب</a>':'')+'<div class="sx-market-notice">تنبيه: الإعلانات التجريبية المعروضة بيانات افتراضية وليست عروضاً موثقة.</div></div>';
 modal.classList.add('open');modal.querySelector('[data-close]').addEventListener('click',function(){modal.classList.remove('open')});
}
function openForm(){var m=document.getElementById('sx-market-add-modal');if(m)m.classList.add('open')}
function closeModals(){document.querySelectorAll('.sx-market-modal').forEach(function(m){m.classList.remove('open')})}
function mount(){
 if(document.getElementById('sx-market-listings'))return;
 var target=document.getElementById('latest-ads');if(!target)return;
 target.innerHTML='<div class="sx-wrap"><div class="sx-market-toolbar"><div><span class="sx-kicker">تصفح السوق</span><h2>إعلانات للبيع والخدمات</h2><span class="sx-market-count"></span></div><button class="sx-button" type="button" id="sx-open-add">＋ أضف إعلانك مجاناً</button></div><div class="sx-market-layout" id="sx-market-listings"><aside class="sx-market-sidebar"><h3>الأقسام</h3><div class="sx-market-filter">'+cats.map(function(c){return '<button type="button" data-cat="'+c+'" class="'+(c==='الكل'?'active':'')+'">'+c+'</button>'}).join('')+'</div></aside><div class="sx-market-main"><div class="sx-market-main-head"><strong>تصفح أحدث الإعلانات</strong><select class="sx-market-sort" id="sx-market-sort"><option value="new">الأحدث أولاً</option><option value="price">السعر (بيانات العرض)</option></select></div><div class="sx-listing-grid"></div></div></div></div>';
 var add=document.createElement('button');add.type='button';add.className='sx-market-submit';add.id='sx-floating-add';add.textContent='+ أضف إعلانك';document.body.appendChild(add);
 var addModal=document.createElement('div');addModal.className='sx-market-modal';addModal.id='sx-market-add-modal';
 addModal.innerHTML='<div class="sx-market-dialog"><div class="sx-market-dialog-head"><h2>أضف إعلانك مجاناً</h2><button class="sx-market-close" type="button" data-close>×</button></div><div class="sx-market-notice">تظهر هنا تلقائياً الإعلانات المنشورة كمنشورات في بلوجر. هذا النموذج التجريبي يحفظ على هذا المتصفح فقط؛ لا يمكنه إنشاء منشور عام في بلوجر دون صلاحية OAuth آمنة.</div><form class="sx-market-form" id="sx-market-form"><div class="sx-market-field full"><label>عنوان الإعلان *</label><input name="title" required maxlength="90" placeholder="مثال: شقة للإيجار في الرياض"/></div><div class="sx-market-field"><label>القسم *</label><select name="category" required>'+cats.slice(1).map(function(c){return '<option>'+c+'</option>'}).join('')+'</select></div><div class="sx-market-field"><label>السعر</label><input name="price" placeholder="مثال: 2500 ريال"/></div><div class="sx-market-field"><label>المدينة *</label><input name="city" required placeholder="الرياض"/></div><div class="sx-market-field"><label>رقم التواصل (اختياري)</label><input name="phone" inputmode="tel" placeholder="9665xxxxxxxx"/></div><div class="sx-market-field full"><label>رابط صورة (اختياري)</label><input name="image" type="url" placeholder="https://..."/></div><div class="sx-market-field full"><label>وصف الإعلان *</label><textarea name="description" required maxlength="1200" placeholder="اكتب تفاصيل الإعلان بوضوح..."></textarea></div><div class="sx-market-disclaimer">بيانات الإعلانات الموجودة حالياً أمثلة افتراضية. لا تستخدم المنصة لإرسال بيانات حساسة، وتحقق من المعلن والسلعة قبل الدفع.</div><button type="submit">حفظ معاينة الإعلان على هذا الجهاز</button></form></div>';
 document.body.appendChild(addModal);
 var detail=document.createElement('div');detail.className='sx-market-modal';detail.id='sx-market-detail-modal';detail.innerHTML='<div class="sx-market-dialog"></div>';document.body.appendChild(detail);
 document.getElementById('sx-open-add').addEventListener('click',openForm);add.addEventListener('click',openForm);
 document.querySelectorAll('.sx-market-close').forEach(function(b){b.addEventListener('click',closeModals)});
 document.querySelectorAll('.sx-market-modal').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)closeModals()})});
 document.querySelectorAll('.sx-market-filter button').forEach(function(b){b.addEventListener('click',function(){active=b.getAttribute('data-cat');document.querySelectorAll('.sx-market-filter button').forEach(function(x){x.classList.toggle('active',x===b)});render()})});
 document.getElementById('sx-market-form').addEventListener('submit',function(e){
  e.preventDefault();var fd=new FormData(e.currentTarget);var x={t:fd.get('title').trim(),c:fd.get('category'),p:fd.get('price').trim()||'على السوم',city:fd.get('city').trim(),phone:fd.get('phone').trim(),image:fd.get('image').trim(),d:fd.get('description').trim(),i:'🛍️',date:'الآن'};
  if(!x.t||!x.city||!x.d)return;
  var list=users();list.unshift(x);if(!save(list)){alert('تعذر حفظ الإعلان. قد تكون مساحة التخزين ممتلئة.');return}
  e.currentTarget.reset();closeModals();active='الكل';document.querySelectorAll('.sx-market-filter button').forEach(function(b){b.classList.toggle('active',b.getAttribute('data-cat')==='الكل')});render();alert('تم حفظ معاينة الإعلان على هذا الجهاز فقط. لن يظهر للزوار الآخرين حتى يُنشر كمنشور في بلوجر.');
 });
 var search=document.querySelector('.sx-market-search input');if(search)search.addEventListener('input',function(){query=search.value;render()});
 var topSearch=document.querySelector('.sx-search input');if(topSearch)topSearch.addEventListener('input',function(){query=topSearch.value;render()});
 render();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount);else mount();
})();
